create or replace function private.spike_is_blocked_between(p_target_id uuid) returns boolean language sql stable security definer set search_path=pg_catalog,public,private as $$ select auth.uid() is not null and exists(select 1 from public.blocks b where (b.blocker_id=auth.uid() and b.blocked_id=p_target_id) or (b.blocker_id=p_target_id and b.blocked_id=auth.uid())); $$;
revoke all on function private.spike_is_blocked_between(uuid) from public,anon;
grant execute on function private.spike_is_blocked_between(uuid) to authenticated;
create or replace function public.spike_discover_public_members(p_query text default null,p_limit integer default 30,p_offset integer default 0) returns table(id uuid,username text,display_name text,avatar_url text,verified boolean,spike_id text,created_at timestamptz) language sql stable security invoker set search_path=pg_catalog,public,private as $$ select p.id,p.username,p.display_name,case when p.avatar_path is null then null when p.avatar_path like 'http%' then p.avatar_path else 'https://veagqanfilmbchlvlpcc.supabase.co/storage/v1/object/public/avatars/'||p.avatar_path end,p.is_verified,p.spike_id,p.created_at from public.profiles p where auth.uid() is not null and p.id<>auth.uid() and p.account_status='active' and p.is_private=false and not private.spike_is_blocked_between(p.id) and (nullif(left(trim(coalesce(p_query,'')),80),'') is null or position(lower(left(trim(p_query),80)) in lower(p.display_name))>0 or position(lower(left(trim(p_query),80)) in lower(p.username))>0 or position(lower(left(trim(p_query),80)) in lower(p.spike_id))>0) and not exists(select 1 from public.follows f where (f.follower_id=auth.uid() and f.following_id=p.id) or (f.follower_id=p.id and f.following_id=auth.uid())) order by p.created_at desc,p.id limit greatest(1,least(coalesce(p_limit,30),50)) offset greatest(0,least(coalesce(p_offset,0),5000)); $$;
revoke all on function public.spike_discover_public_members(text,integer,integer) from public,anon;
grant execute on function public.spike_discover_public_members(text,integer,integer) to authenticated;
